def generate_poly_formula(coeffs, bw_cell):
    terms = []
    for i, c in enumerate(coeffs):
        val = "{:.25f}".format(c).rstrip('0').rstrip('.')
        if i == 0:
            terms.append(f"{val}")
        elif i == 1:
            terms.append(f"{val}*{bw_cell}")
        else:
            terms.append(f"{val}*{bw_cell}^{i}")
    return "+".join(terms)

